1	/**
2	 * Punycode codec — a faithful from-scratch port of CPython's
3	 * `Lib/encodings/punycode.py` (the codec registered as `"punycode"`,
4	 * originally written by Martin v. Löwis), operating in STRICT error mode.
5	 *
6	 * This is deliberately NOT an RFC 3492 reference implementation: CPython's
7	 * codec differs from the RFC in observable ways (no overflow checks, no
8	 * non-minimal-encoding rejection, `.upper()`-folding of the extended part,
9	 * `rfind('-')` delimiter search, initial bias 72 rather than 72-with-basic
10	 * -string special casing, ...). Those quirks are reproduced exactly, because
11	 * matching `str.encode('punycode')` / `bytes.decode('punycode')` is the goal.
12	 *
13	 * Neither function deals with the "xn--" ACE prefix; that belongs to the IDNA
14	 * layer sitting above this one.
15	 *
16	 * Two implementation notes that matter for exactness:
17	 *
18	 *  1. Python iterates strings by CODEPOINT. JavaScript strings are UTF-16, so
19	 *     every place CPython says `for c in str` / `len(str)` / `str[i]` we work
20	 *     on an array of codepoint integers instead of a JS string. This keeps
21	 *     astral-plane characters (and lone surrogates) counted as a single unit,
22	 *     exactly as CPython counts them.
23	 *
24	 *  2. Python integers are arbitrary precision. On the decode side the
25	 *     accumulator `result`, the weight `w`, the running `pos` and the running
26	 *     `char` can all exceed 2**53 for adversarial input, and the
27	 *     `char > 0x10FFFF` guard must fire on the *exact* value CPython would
28	 *     compute. Those quantities are therefore BigInt. Everything bounded by
29	 *     the input length (the bias, `j`, array indices) stays a Number.
30	 *
31	 * @module punycode-codec
32	 */
33	
34	/** Error thrown for every condition where CPython raises `UnicodeError`. */
35	export class PunycodeError extends Error {
36	  constructor(message) {
37	    super(message);
38	    this.name = 'PunycodeError';
39	  }
40	}
41	
42	/** Punycode parameter set: base = 36, tmin = 1, tmax = 26. */
43	const BASE = 36;
44	const TMIN = 1;
45	const TMAX = 26;
46	/** Initial bias, damp and skew, per CPython's `generate_integers` / `adapt`. */
47	const INITIAL_BIAS = 72;
48	const DAMP = 700;
49	const SKEW = 38;
50	/** `((base - tmin) * tmax) // 2`, the `adapt` division threshold. */
51	const ADAPT_THRESHOLD = 455;
52	
53	/** Digit alphabet: values 0..35 map to a-z then 0-9. */
54	const DIGITS = 'abcdefghijklmnopqrstuvwxyz0123456789';
55	
56	const MAX_CODEPOINT = 0x10ffff;
57	
58	/* ------------------------------------------------------------------ */
59	/* Small numeric helpers                                               */
60	/* ------------------------------------------------------------------ */
61	
62	/**
63	 * Python's `//` on integers: floor division, not truncation. Every value we
64	 * feed it is non-negative in practice (so `/` would do), but matching Python's
65	 * rounding direction unconditionally removes a whole class of latent bugs.
66	 */
67	function floorDiv(a, b) {
68	  const q = a / b;
69	  // BigInt `/` truncates toward zero; correct when the true quotient is
70	  // negative and the division was not exact.
71	  return q * b !== a && (a < 0n) !== (b < 0n) ? q - 1n : q;
72	}
73	
74	/**
75	 * `T(j, bias)` — the per-position digit threshold, clamped to [tmin, tmax].
76	 * Returns a Number: `j` is bounded by the input length and `bias` by the
77	 * magnitude of the deltas, so this never leaves the safe-integer range.
78	 */
79	function T(j, bias) {
80	  const res = BASE * (j + 1) - bias;
81	  if (res < TMIN) return TMIN;
82	  if (res > TMAX) return TMAX;
83	  return res;
84	}
85	
86	/**
87	 * Bias adaptation (RFC 3492 §6.1 as CPython spells it).
88	 *
89	 * Computed in BigInt so that a huge `delta` coming out of the decoder adapts
90	 * to exactly the bias CPython would compute. `numchars` is an array length and
91	 * the returned bias is bounded by ~36 * log35(delta), both comfortably within
92	 * Number range for any input that can physically be supplied.
93	 *
94	 * @param {number|bigint} delta
95	 * @param {boolean} first  true for the first delta of the string
96	 * @param {number} numchars
97	 * @returns {number} the new bias
98	 */
99	function adapt(delta, first, numchars) {
100	  let d = BigInt(delta);
101	  d = first ? floorDiv(d, BigInt(DAMP)) : floorDiv(d, 2n);
102	  d += floorDiv(d, BigInt(numchars));
103	  let divisions = 0n;
104	  while (d > BigInt(ADAPT_THRESHOLD)) {
105	    d = floorDiv(d, BigInt(BASE - TMIN)); // base - tmin == 35
106	    divisions += BigInt(BASE);
107	  }
108	  return Number(divisions + floorDiv(BigInt(BASE) * d, d + BigInt(SKEW)));
109	}
110	
111	/**
112	 * Decompose a JS string into codepoints. `Array.from` iterates by codepoint,
113	 * so surrogate pairs collapse to one astral value and lone surrogates survive
114	 * as themselves — which is precisely how CPython would see the same text.
115	 */
116	function toCodepoints(str) {
117	  return Array.from(str, (ch) => ch.codePointAt(0));
118	}
119	
120	/** Rebuild a JS string from an array of codepoints, chunked to avoid blowing
121	 *  the argument limit on very long strings. */
122	function fromCodepoints(cps) {
123	  const CHUNK = 4096;
124	  if (cps.length <= CHUNK) return String.fromCodePoint(...cps);
125	  let out = '';
126	  for (let i = 0; i < cps.length; i += CHUNK) {
127	    out += String.fromCodePoint(...cps.slice(i, i + CHUNK));
128	  }
129	  return out;
130	}
131	
132	/* ------------------------------------------------------------------ */
133	/* Encoding                                                            */
134	/* ------------------------------------------------------------------ */
135	
136	/**
137	 * 3.1 Basic code point segregation.
138	 *
139	 * `base` keeps every codepoint < 128 in order; `extended` is the
140	 * deduplicated, ascending-sorted set of codepoints >= 128.
141	 */
142	function segregate(cps) {
143	  const base = [];
144	  const seen = new Set();
145	  for (const cp of cps) {
146	    if (cp < 128) base.push(cp);
147	    else seen.add(cp);
148	  }
149	  const extended = Array.from(seen).sort((a, b) => a - b);
150	  return { base, extended };
151	}
152	
153	/** Number of codepoints in `cps` strictly below `max`. */
154	function selectiveLen(cps, max) {
155	  let res = 0;
156	  for (const cp of cps) {
157	    if (cp < max) res += 1;
158	  }
159	  return res;
160	}
161	
162	/**
163	 * Next occurrence of `char` in `cps`, returned as `[index, pos]` where `pos`
164	 * is the position in the full text and `index` counts only codepoints up to
165	 * and including `char`. `[-1, -1]` signals "no more occurrences".
166	 */
167	function selectiveFind(cps, char, index, pos) {
168	  const l = cps.length;
169	  for (;;) {
170	    pos += 1;
171	    if (pos === l) return [-1, -1];
172	    const c = cps[pos];
173	    if (c === char) return [index + 1, pos];
174	    else if (c < char) index += 1;
175	  }
176	}
177	
178	/**
179	 * 3.2 Insertion unsort coding — turns the text into the delta sequence that
180	 * replays the insertions in codepoint order.
181	 */
182	function insertionUnsort(cps, extended) {
183	  let oldchar = 0x80;
184	  const result = [];
185	  let oldindex = -1;
186	  for (const char of extended) {
187	    let index = -1;
188	    let pos = -1;
189	    const curlen = selectiveLen(cps, char);
190	    // Deltas stay bounded by (text length + 1) * 0x10FFFF, so Number is exact
191	    // on the encode side; only the decoder can be handed unbounded values.
192	    let delta = (curlen + 1) * (char - oldchar);
193	    for (;;) {
194	      [index, pos] = selectiveFind(cps, char, index, pos);
195	      if (index === -1) break;
196	      delta += index - oldindex;
197	      result.push(delta - 1);
198	      oldindex = index;
199	      delta = 0;
200	    }
201	    oldchar = char;
202	  }
203	  return result;
204	}
205	
206	/** 3.3 Generalized variable-length integers (encode direction). */
207	function generateGeneralizedInteger(N, bias) {
208	  let out = '';
209	  let j = 0;
210	  for (;;) {
211	    const t = T(j, bias);
212	    if (N < t) {
213	      out += DIGITS[N];
214	      return out;
215	    }
216	    out += DIGITS[t + ((N - t) % (BASE - t))];
217	    N = Math.floor((N - t) / (BASE - t));
218	    j += 1;
219	  }
220	}
221	
222	/** 3.4 Bias adaptation over the whole delta sequence. */
223	function generateIntegers(baselen, deltas) {
224	  let out = '';
225	  let bias = INITIAL_BIAS;
226	  for (let points = 0; points < deltas.length; points++) {
227	    const delta = deltas[points];
228	    out += generateGeneralizedInteger(delta, bias);
229	    bias = adapt(delta, points === 0, baselen + points + 1);
230	  }
231	  return out;
232	}
233	
234	/**
235	 * Encode a string to punycode, WITHOUT the "xn--" prefix.
236	 *
237	 * Mirrors `str.encode('punycode')`: the ASCII part is emitted verbatim and,
238	 * when non-empty, separated from the extended part by a literal "-" — note
239	 * that a purely-ASCII input therefore always gains a trailing "-", and an
240	 * empty input encodes to the empty string.
241	 *
242	 * @param {string} str
243	 * @returns {string} ASCII punycode
244	 */
245	export function punycodeEncode(str) {
246	  const cps = toCodepoints(String(str));
247	  const { base, extended } = segregate(cps);
248	  const deltas = insertionUnsort(cps, extended);
249	  // `len(base)` in CPython is the ASCII codepoint count.
250	  const ext = generateIntegers(base.length, deltas);
251	  if (base.length > 0) return fromCodepoints(base) + '-' + ext;
252	  return ext;
253	}
254	
255	/* ------------------------------------------------------------------ */
256	/* Decoding (strict)                                                   */
257	/* ------------------------------------------------------------------ */
258	
259	/** Python's `repr()` of a single character, as used in UnicodeEncodeError. */
260	function pyCharRepr(cp) {
261	  const hex = (n, w) => n.toString(16).padStart(w, '0');
262	  if (cp < 0x100) return `'\\x${hex(cp, 2)}'`;
263	  if (cp < 0x10000) return `'\\u${hex(cp, 4)}'`;
264	  return `'\\U${hex(cp, 8)}'`;
265	}
266	
267	/**
268	 * 3.3 Generalized variable-length integers (decode direction).
269	 *
270	 * `result` and `w` are BigInt: CPython uses unbounded ints here and a long
271	 * run of high digits genuinely overflows 2**53.
272	 *
273	 * @returns {[number, bigint]} `[newExtpos, value]`
274	 */
275	function decodeGeneralizedNumber(extended, extpos, bias) {
276	  let result = 0n;
277	  let w = 1n;
278	  let j = 0;
279	  for (;;) {
280	    if (extpos >= extended.length) {
281	      // CPython's spelling of the message, typo included.
282	      throw new PunycodeError('incomplete punicode string');
283	    }
284	    const code = extended.charCodeAt(extpos);
285	    extpos += 1;
286	    let digit;
287	    if (code >= 0x41 && code <= 0x5a) {
288	      digit = code - 0x41; // A-Z -> 0..25
289	    } else if (code >= 0x30 && code <= 0x39) {
290	      digit = code - 22; // 0-9 -> 26..35
291	    } else {
292	      throw new PunycodeError(
293	        `Invalid extended code point '${extended[extpos - 1]}'`
294	      );
295	    }
296	    const t = T(j, bias);
297	    result += BigInt(digit) * w;
298	    if (digit < t) return [extpos, result];
299	    w = w * BigInt(BASE - t);
300	    j += 1;
301	  }
302	}
303	
304	/**
305	 * 3.2 Insertion sort coding — replays the deltas, inserting one codepoint per
306	 * delta into `base`.
307	 *
308	 * `base` is carried as an array of codepoints, not a JS string, so that
309	 * `len(base)` matches CPython's character count even once astral codepoints
310	 * (or bare surrogates) have been inserted.
311	 */
312	function insertionSort(baseCps, extended) {
313	  const base = baseCps.slice();
314	  let char = 0x80n;
315	  let pos = -1n;
316	  let bias = INITIAL_BIAS;
317	  let extpos = 0;
318	
319	  while (extpos < extended.length) {
320	    const [newpos, delta] = decodeGeneralizedNumber(extended, extpos, bias);
321	    pos += delta + 1n;
322	    // `len(base) + 1` is recomputed every round: base grows by one codepoint
323	    // per insertion.
324	    const denom = BigInt(base.length + 1);
325	    char += floorDiv(pos, denom);
326	    if (char > BigInt(MAX_CODEPOINT)) {
327	      // Python's "%x": lowercase hex, no prefix.
328	      throw new PunycodeError(`Invalid character U+${char.toString(16)}`);
329	    }
330	    pos = ((pos % denom) + denom) % denom; // Python's non-negative %
331	    base.splice(Number(pos), 0, Number(char));
332	    // Note: `adapt` gets the length AFTER the insertion, and `extpos` is still
333	    // the pre-advance value, so `extpos === 0` marks the first delta.
334	    bias = adapt(delta, extpos === 0, base.length);
335	    extpos = newpos;
336	  }
337	  return base;
338	}
339	
340	/**
341	 * Decode a punycode string (WITHOUT the "xn--" prefix) in strict mode.
342	 *
343	 * Mirrors `bytes.decode('punycode')`: the delimiter is the LAST "-" in the
344	 * whole string, the extended part is upper-cased before decoding (so the
345	 * codec is case-insensitive on its digits), and a string with no "-" at all is
346	 * treated as entirely extended.
347	 *
348	 * @param {string} ascii
349	 * @returns {string}
350	 */
351	export function punycodeDecode(ascii) {
352	  const text = String(ascii);
353	
354	  // CPython does `text.encode("ascii")` first, which rejects non-ASCII input
355	  // before any punycode logic runs. The reported position is a codepoint
356	  // index, tracked explicitly rather than inferred from indexOf.
357	  let cpIndex = 0;
358	  for (const ch of text) {
359	    const cp = ch.codePointAt(0);
360	    if (cp > 0x7f) {
361	      throw new PunycodeError(
362	        `'ascii' codec can't encode character ${pyCharRepr(cp)} in position ` +
363	          `${cpIndex}: ordinal not in range(128)`
364	      );
365	    }
366	    cpIndex += 1;
367	  }
368	
369	  const pos = text.lastIndexOf('-');
370	  let baseStr;
371	  let extended;
372	  if (pos === -1) {
373	    baseStr = '';
374	    extended = text.toUpperCase();
375	  } else {
376	    baseStr = text.slice(0, pos);
377	    extended = text.slice(pos + 1).toUpperCase();
378	  }
379	
380	  return fromCodepoints(insertionSort(toCodepoints(baseStr), extended));
381	}
