1	/**
2	 * Self-test for /tmp/wf/punycode-codec.mjs
3	 *
4	 * Asserts the punycode codec against every vector supplied with the task
5	 * (all confirmed against the reference oracle and/or CPython's
6	 * `str.encode('punycode')`), plus round-trips, astral-plane coverage and the
7	 * strict-mode error surface.
8	 *
9	 * Run: node /tmp/wf/punycode-selftest.mjs
10	 */
11	
12	import { strict as assert } from 'node:assert';
13	import {
14	  punycodeEncode,
15	  punycodeDecode,
16	  PunycodeError,
17	} from '/tmp/wf/punycode-codec.mjs';
18	
19	let passed = 0;
20	let failed = 0;
21	
22	function check(label, fn) {
23	  try {
24	    fn();
25	    passed += 1;
26	  } catch (err) {
27	    failed += 1;
28	    console.error(`FAIL  ${label}\n      ${err.message}`);
29	  }
30	}
31	
32	function eqEncode(input, expected) {
33	  check(`encode ${JSON.stringify(input)} -> ${expected}`, () => {
34	    assert.equal(punycodeEncode(input), expected);
35	  });
36	}
37	
38	function eqDecode(input, expected) {
39	  check(`decode ${JSON.stringify(input)} -> ${JSON.stringify(expected)}`, () => {
40	    assert.equal(punycodeDecode(input), expected);
41	  });
42	}
43	
44	/** Both directions, from a full "xn--"-prefixed A-label. */
45	function vector(unicode, alabel) {
46	  assert.ok(alabel.startsWith('xn--'), `bad test vector: ${alabel}`);
47	  const puny = alabel.slice(4);
48	  eqEncode(unicode, puny);
49	  eqDecode(puny, unicode);
50	}
51	
52	/* ------------------------------------------------------------------ */
53	/* 1. Task-supplied vectors (oracle-confirmed A-labels)                */
54	/* ------------------------------------------------------------------ */
55	
