165	/* ------------------------------------------------------------------ */
166	/* 5. Strict-mode errors (messages match CPython verbatim)             */
167	/* ------------------------------------------------------------------ */
168	
169	function throwsWith(label, fn, message) {
170	  check(label, () => {
171	    assert.throws(fn, (err) => {
172	      assert.ok(
173	        err instanceof PunycodeError,
174	        `expected PunycodeError, got ${err && err.name}`
175	      );
176	      assert.ok(err instanceof Error, 'PunycodeError must subclass Error');
177	      assert.equal(err.message, message);
178	      return true;
179	    });
180	  });
181	}
182	
183	throwsWith(
184	  'incomplete string',
185	  () => punycodeDecode('z'),
186	  'incomplete punicode string'
187	);
188	throwsWith(
189	  'incomplete string (long)',
190	  () => punycodeDecode('zzzzzzzzzzzz'),
191	  'incomplete punicode string'
192	);
